#!/usr/bin/env bash
# Verify that tools/ci/apply_pigweed_patches.py is idempotent and that its
# output matches the reviewed patches/0001-avr-pw-transfer-and-protobuf.patch.
#
# Usage:
#   tools/ci/check_pigweed_patches.sh            # verify
#   tools/ci/check_pigweed_patches.sh --update   # regenerate the .patch file
#
# Diffs use --full-index so the file is identical regardless of clone depth
# (abbreviated object IDs differ between shallow CI clones and full clones).
#
# WARNING: discards uncommitted changes in third_party/pigweed (they are fully
# regenerated by apply_pigweed_patches.py).
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
PW_ROOT="${ROOT}/third_party/pigweed"
PATCH_FILE="${ROOT}/patches/0001-avr-pw-transfer-and-protobuf.patch"
APPLY="${ROOT}/tools/ci/apply_pigweed_patches.py"

git -C "${PW_ROOT}" checkout -- .

python3 "${APPLY}" >/dev/null
first="$(git -C "${PW_ROOT}" diff --full-index)"

python3 "${APPLY}" >/dev/null
second="$(git -C "${PW_ROOT}" diff --full-index)"

if [[ "${first}" != "${second}" ]]; then
    echo "ERROR: apply_pigweed_patches.py is not idempotent; a second run changed:" >&2
    diff <(printf '%s\n' "${first}") <(printf '%s\n' "${second}") | head -40 >&2
    exit 1
fi
echo "[OK] apply_pigweed_patches.py is idempotent"

if [[ "${1:-}" == "--update" ]]; then
    printf '%s\n' "${second}" > "${PATCH_FILE}"
    echo "[OK] Regenerated ${PATCH_FILE#"${ROOT}"/}"
    exit 0
fi

if ! diff -u "${PATCH_FILE}" <(printf '%s\n' "${second}") >/dev/null; then
    echo "ERROR: ${PATCH_FILE#"${ROOT}"/} is stale relative to apply_pigweed_patches.py." >&2
    echo "Run: tools/ci/check_pigweed_patches.sh --update" >&2
    diff -u "${PATCH_FILE}" <(printf '%s\n' "${second}") | head -60 >&2
    exit 1
fi
echo "[OK] ${PATCH_FILE#"${ROOT}"/} matches the scripted delta"
